function detectUiLang() {
  const list = (navigator.languages && navigator.languages.length) ? navigator.languages : [navigator.language || ''];
  for (const item of list) {
    const base = String(item || '').toLowerCase().split(/[-_]/)[0];
    if (UI_LANGS.some((l) => l.code === base)) return base;
  }
  return 'en';
}

// 接口里的 i18n 对象键名可能是 zh / zh-CN / zh_CN，按语言基码宽松匹配
function pickI18n(obj, lang) {
  if (!obj || typeof obj !== 'object') return '';
  const want = String(lang || '').toLowerCase();
  const base = want.split(/[-_]/)[0];
  if (!base) return '';
  for (const key of Object.keys(obj)) {
    const k = key.toLowerCase();
    if (k === want || k === base || k.split(/[-_]/)[0] === base) {
      const value = obj[key];
      if (typeof value === 'string' && value) return value;
    }
  }
  return '';
}

